parameters.jsCode:
const mensaje = ($json.output || '')
  .replace(/\*/g, '')
  .replace(/_/g, '');

return [{
  chat_id: $('Telegram Trigger').first().json.message.chat.id,
  mensaje,
  longitud_mensaje: mensaje.length
}];

